import{_ as e,o as i,c as t,a3 as a}from"./chunks/framework.DAK02U1-.js";const k=JSON.parse('{"title":"Test and Debug","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Test and Debug | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/clice/dev/test-and-debug"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/clice/dev/test-and-debug"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/clice/dev/test-and-debug"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/clice/dev/test-and-debug"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/clice/dev/test-and-debug"}]]},"headers":[],"relativePath":"clice/dev/test-and-debug.md","filePath":"en/clice/dev/test-and-debug.md","lastUpdated":1792529560000}'),n={name:"clice/dev/test-and-debug.md"};function l(h,s,o,p,d,c){return i(),t("div",null,[...s[0]||(s[0]=[a(`<h1 id="test-and-debug" tabindex="-1">Test and Debug <a class="header-anchor" href="#test-and-debug" aria-label="Permalink to &quot;Test and Debug&quot;">​</a></h1><h2 id="run-tests" tabindex="-1">Run Tests <a class="header-anchor" href="#run-tests" aria-label="Permalink to &quot;Run Tests&quot;">​</a></h2><p>clice has two test suites that run on every change: the unit tests and the cases. Compatibility tests, which need real build systems and compilers, and the editor tests run separately.</p><p>All test dependencies (node/npm for the cases and tools, python for scripts/) are managed by pixi — no separate installation needed.</p><h3 id="unit-tests" tabindex="-1">Unit Tests <a class="header-anchor" href="#unit-tests" aria-label="Permalink to &quot;Unit Tests&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pixi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unit-test</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # default RelWithDebInfo</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pixi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unit-test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Debug</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # debug build</span></span></code></pre></div><p>Equivalent to:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build/RelWithDebInfo/bin/bin/unittests</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --verbose</span></span></code></pre></div><h3 id="cases" tabindex="-1">Cases <a class="header-anchor" href="#cases" aria-label="Permalink to &quot;Cases&quot;">​</a></h3><p>Every other test is a case under <code>tests/&lt;topic&gt;/&lt;subtopic&gt;/NN_name/</code>: a small project of its own, the checks to run on it, and <code>snap.toml</code>, every output the case pins. A case asks a real <code>clice serve</code>, <code>clice inspect</code> or a command, through the framework in <code>tools/testing/</code>, and the feature pages of these docs show the cases that have a <code>README.md</code>. <a href="https://github.com/clice-io/clice/blob/main/tests/README.md" target="_blank" rel="noreferrer"><code>tests/README.md</code></a> is the contract: how a case is written, how it asserts and how its output reads.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pixi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cases-test</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # default RelWithDebInfo</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pixi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cases-test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Debug</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # debug build</span></span></code></pre></div><p>Equivalent to:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CLICE_EXECUTABLE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PWD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/build/RelWithDebInfo/bin/bin/clice</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cases</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --workspace</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests</span></span></code></pre></div><p><code>CLICE_CASES=hover/</code> runs the cases under a path. <code>UPDATE_SNAPSHOTS=1</code> rewrites their outputs and prints which changed; review the change like code.</p><p>A change to the TypeScript also passes <code>npm run check</code> at the repository root: strict tsc and ESLint over every package. <code>npm test --workspace tools</code> runs the tools&#39; own tests.</p><h3 id="run-all-tests" tabindex="-1">Run All Tests <a class="header-anchor" href="#run-all-tests" aria-label="Permalink to &quot;Run All Tests&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pixi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                # runs unit + cases</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pixi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Debug</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # all tests with debug build</span></span></code></pre></div><h2 id="editor-e2e-tests" tabindex="-1">Editor E2E Tests <a class="header-anchor" href="#editor-e2e-tests" aria-label="Permalink to &quot;Editor E2E Tests&quot;">​</a></h2><p>Smoke tests that run real editors (headless Neovim and VSCode) against a locally built clice binary, covering startup, first diagnostics, hover, definition and completion, and on a header the commands that show and switch its compilation context. They run on copies of three cases — a single file, a C++20 modules project and a header with two hosts — that <code>editor-prepare</code> writes under <code>.cache/editors</code>. CI runs them on the Linux x64 and macOS arm64 legs with the latest stable editor releases, on purpose unpinned: the job exists to catch breakage caused by new editor versions.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pixi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                  # build/RelWithDebInfo/bin/bin/clice</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pixi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> editor</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> editor-test</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # nvim + vscode, all three projects</span></span></code></pre></div><p>Prerequisites outside the pixi env:</p><ul><li><code>nvim</code> (stable) on <code>PATH</code> for <code>nvim-e2e</code>.</li><li>A display (or <code>xvfb-run</code>) plus the usual Electron system libraries for <code>vscode-e2e</code>.</li></ul><h2 id="compatibility-tests" tabindex="-1">Compatibility Tests <a class="header-anchor" href="#compatibility-tests" aria-label="Permalink to &quot;Compatibility Tests&quot;">​</a></h2><p>Real build systems and real compilers: each scenario in <code>tests/compat/scenarios.ts</code> builds the small project under <code>tests/compat/project/</code> with one build system and one toolchain, then runs clice over the compilation database that build wrote. Every translation unit must parse without errors, as it compiled for the real compiler; clice must agree with that compiler on the macros the command&#39;s flags imply, which a generated header compares inside clice&#39;s own parse; and each file&#39;s command must resolve through the compiler and keep or drop the flags the scenario lists. No database is committed: the suite checks what the tools write today.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pixi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compat-test</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # default RelWithDebInfo</span></span></code></pre></div><p>Each scenario names the compilers of one platform as its CI runner image has them: on Linux the distribution&#39;s versioned GCC and Clang plus bear, ccache, meson, ninja, xmake, bazel, zig, Emscripten, the MinGW, RISC-V and Arm cross compilers, and nvcc from the pixi <code>cuda</code> environment (<code>pixi install -e cuda</code>); on Windows Visual Studio, LLVM and MinGW; on macOS Apple clang and Homebrew&#39;s GCC and LLVM. A scenario whose tools are missing is skipped locally and fails in CI. CI runs the suite with every build, and weekly against the newest release.</p><h2 id="debug" tabindex="-1">Debug <a class="header-anchor" href="#debug" aria-label="Permalink to &quot;Debug&quot;">​</a></h2><p>If you want to attach a debugger to clice, start it in socket mode independently, then connect a client.</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build/Debug/bin/bin/clice</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --mode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> socket</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 50051</span></span></code></pre></div><p>After the server starts, you can connect a client in two ways:</p><h3 id="connect-via-vs-code" tabindex="-1">Connect via VS Code <a class="header-anchor" href="#connect-via-vs-code" aria-label="Permalink to &quot;Connect via VS Code&quot;">​</a></h3><p>Configure the clice extension to connect to your running instance:</p><ol><li><p>Install the <a href="https://marketplace.visualstudio.com/items?itemName=clice-io.clice" target="_blank" rel="noreferrer">clice</a> extension.</p></li><li><p>Configure <code>.vscode/settings.json</code>:</p><div class="language-jsonc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">jsonc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;clice.executable&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/path/to/your/clice/executable&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;clice.mode&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;socket&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;clice.port&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">50051</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // Optional: disable clangd if also installed</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;clangd.path&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div></li><li><p>Reload Window (<code>Developer: Reload Window</code>) for settings to take effect.</p></li></ol><h3 id="debug-the-vs-code-extension" tabindex="-1">Debug the VS Code extension <a class="header-anchor" href="#debug-the-vs-code-extension" aria-label="Permalink to &quot;Debug the VS Code extension&quot;">​</a></h3><p>The extension lives in-tree at <code>editors/vscode/</code>:</p><ol><li><p>Install dependencies:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # at the repo root; the extension is an npm workspace member</span></span></code></pre></div></li><li><p>Open the <strong>repository root</strong> in VS Code (the launch configurations are in <code>.vscode/launch.json</code> at the root).</p></li><li><p>Create <code>.vscode/settings.json</code> with the tcp config above.</p></li><li><p>Press <code>F5</code> and select <code>VSCode Extension (pipe)</code> or <code>VSCode Extension (socket)</code> to launch an Extension Development Host window.</p></li></ol>`,36)])])}const u=e(n,[["render",l]]);export{k as __pageData,u as default};
